function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.circle(0, 0, 200);

  // Hills
  brush.fill("#98FB98", 70);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(200, 100);
  brush.vertex(400, 0);
  brush.endShape(true);

  // Sun
  brush.fill("#FF4500", 100);
  brush.beginShape();
  brush.vertex(200, 50);
  brush.vertex(220, 10);
  brush.vertex(240, 30);
  brush.endShape(true);
}
